import java.lang.annotation.ElementType;
import java.lang.annotation.Retention;
import java.lang.annotation.RetentionPolicy;
import java.lang.annotation.Target;
import java.lang.reflect.Field;

public class Main {
    @Retention(RetentionPolicy.RUNTIME)
    @Target(ElementType.FIELD)
    @interface 纸条 {
        String value();
    }

    static class 小猫 {
        @纸条("私房")
        private String 名字 = "小橘";
        int 小鱼干 = 3;
    }

    public static void main(String[] args) throws Exception {
        for (String 名字 : new String[]{"名字", "小鱼干"}) {
            Field 骨头 = 小猫.class.getDeclaredField(名字);
            纸条 小纸条 = 骨头.getAnnotation(纸条.class);
            System.out.println(名字 + "：" + (小纸条 == null ? "没贴" : 小纸条.value()));
        }
    }
}

import java.lang.reflect.Field;
import java.lang.reflect.Method;

public class Main {
    @interface 纸条 {
        String value();
    }

    static class 小猫 {
        @纸条("开饭了")
        void 打招呼() {
        }

        @纸条("私房")
        String 名字 = "小橘";
    }

    public static void main(String[] args) throws Exception {
        Method 一招 = 小猫.class.getDeclaredMethod("打招呼");
        Field 骨头 = 小猫.class.getDeclaredField("名字");
        System.out.println("招式上贴了吗：" + 一招.isAnnotationPresent(纸条.class));
        System.out.println("光片上读到：" + 骨头.getAnnotation(纸条.class));
    }
}
